require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../lib/PayrollRepository.php';if(!PayrollRepository::canManage()&&!Auth::can('payroll.view_all')){http_response_code(403);exit('دسترسی غیرمجاز است.');}$pageTitle='فیش‌های حقوقی';$adminExtraStylesheets=['/assets/css/workforce.css'];$periodId=(int)($_GET['period_id']??0);$q=trim((string)($_GET['q']??''));$status=(string)($_GET['status']??'');$where=['1=1'];$params=[];if($periodId){$where[]='s.period_id=?';$params[]=$periodId;}if($q!==''){$where[]='(u.name LIKE ? OR s.employee_no LIKE ?)';$params[]='%'.$q.'%';$params[]='%'.$q.'%';}if(in_array($status,['draft','ready','published','cancelled'],true)){$where[]='s.status=?';$params[]=$status;}$slips=Database::fetchAll('SELECT s.*,p.title period_title,p.period_key,p.status period_status,u.name employee_name,ou.title unit_title FROM payroll_slips s JOIN payroll_periods p ON p.id=s.period_id JOIN users u ON u.id=s.user_id LEFT JOIN org_units ou ON ou.id=u.org_unit_id WHERE '.implode(' AND ',$where).' ORDER BY p.year DESC,p.month DESC,u.name',$params);$periods=Database::fetchAll('SELECT id,title,period_key FROM payroll_periods ORDER BY year DESC,month DESC');require __DIR__.'/../views/partials/admin-header.php';?>
<div class="workforce-head"><div><h1>فیش‌های حقوقی</h1><p>مشاهده فیش‌های آماده و منتشرشده</p></div><a class="btn" href="/admin/payroll-export.php<?= $periodId?'?period_id='.$periodId:'' ?>">خروجی گروهی</a></div><nav class="workforce-tabs"><a href="/admin/payroll-periods.php">دوره‌ها</a><a href="/admin/payroll-fields.php">فیلدها</a><a href="/admin/payroll-import.php">ایمپورت</a><a class="is-active" href="/admin/payroll-slips.php">فیش‌ها</a></nav><section class="card"><form method="get" class="compact-grid"><label class="form-field"><span>نام یا شماره پرسنلی</span><input name="q" value="<?=e($q)?>"></label><label class="form-field"><span>دوره</span><select name="period_id"><option value="">همه</option><?php foreach($periods as $p):?><option value="<?=$p['id']?>" <?=$periodId===$p['id']?'selected':''?>><?=e($p['title'])?></option><?php endforeach?></select></label><label class="form-field"><span>وضعیت</span><select name="status"><option value="">همه</option><?php foreach(['draft'=>'پیش‌نویس','ready'=>'آماده','published'=>'منتشرشده','cancelled'=>'لغوشده'] as $k=>$v):?><option value="<?=$k?>" <?=$status===$k?'selected':''?>><?=$v?></option><?php endforeach?></select></label><button class="btn btn-primary">فیلتر</button></form></section><section class="card"><div class="table-wrap"><table><thead><tr><th>کارمند</th><th>دوره</th><th>مزایا</th><th>کسورات</th><th>خالص</th><th>وضعیت</th><th></th></tr></thead><tbody><?php foreach($slips as $s):?><tr><td><strong><?=e($s['employee_name'])?></strong><small><?=e($s['employee_no'].' — '.($s['unit_title']?:'بدون واحد'))?></small></td><td><?=e($s['period_title'])?></td><td><?=e(format_money($s['total_earnings']))?></td><td><?=e(format_money($s['total_deductions']))?></td><td><strong><?=e(format_money($s['net_pay']))?></strong></td><td><span class="workforce-status status-<?=e($s['status'])?>"><?=e($s['status'])?></span></td><td><a class="btn btn-small" href="/admin/payroll-slip-view.php?id=<?=$s['id']?>">مشاهده</a></td></tr><?php endforeach?><?php if(!$slips):?><tr><td colspan="7">فیشی پیدا نشد.</td></tr><?php endif?></tbody></table></div></section><?php require __DIR__.'/../views/partials/admin-footer.php';?>
